/** Run manually from the Apps Script editor as the hospital account. Idempotent. */
function setupHospital_(){
 if(props_().getProperty('DB_ID')){console.log('Already configured.');return;}
 const email=Session.getEffectiveUser().getEmail().toLowerCase();if(!email)throw Error('Owner email unavailable.');
 const root=DriveApp.createFolder('Visa Medical');const db=SpreadsheetApp.create('Visa Medical Private Database');DriveApp.getFileById(db.getId()).moveTo(root);
 const spec={Users:['Email','Name','Role','Active'],Cases:['ID','Form No.','Patient','Passport','Revision','File ID','Created','Updated','FO Register Row','Admin Register Row'],Audit:['Time','Actor','Action','ID'],Devices:['ID','Token hash','Expires','Active','Label','Request File ID']};
 for(const n in spec){const s=db.insertSheet(n);s.appendRow(spec[n]);s.setFrozenRows(1);}
 db.deleteSheet(db.getSheetByName('Sheet1'));
 const values={DB_ID:db.getId(),ROOT_ID:root.getId(),OWNER_EMAIL:email};
 for(const key of ['TEMPLATES','RECORDS','SIGNATURES','EXPORTS','REQUESTS'])values[key+'_ID']=root.createFolder(key[0]+key.slice(1).toLowerCase()).getId();
 props_().setProperties(values);sheet_('Users').appendRow([email,'Hospital Owner','SUPERADMIN',true]);
 file_(folder_('TEMPLATES_ID'),'field-schema-v1.json',{version:1,fields:DEFAULT_FIELDS});
 props_().setProperty('SCHEMA_ID',folder_('TEMPLATES_ID').getFilesByName('field-schema-v1.json').next().getId());
 audit_(email,'SETUP','');console.log('Owner '+email+'. Now run installTemplates.');
}
/** Run manually after setup. Preserves supplied source files byte-for-byte. Can resume. */
function installTemplates_(){
 if(Session.getEffectiveUser().getEmail().toLowerCase()!==props_().getProperty('OWNER_EMAIL'))throw Error('Owner only.');
 const folder=folder_('TEMPLATES_ID');
 packageAssets_().forEach(a=>{if(!folder.getFilesByName(a.name).hasNext())folder.createFile(Utilities.newBlob(Utilities.base64Decode(a.data),a.mime,a.name));});
 for(const side of ['fo','admin']){
  const key='REGISTER_'+side.toUpperCase()+'_ID';
  if(!props_().getProperty(key)){
   const source=asset_('runtime-'+side+'.xlsx');
   const f=Drive.Files.create({name:'Workpermit Register ('+(side==='fo'?'FO':'Admin')+')',mimeType:'application/vnd.google-apps.spreadsheet',parents:[props_().getProperty('ROOT_ID')]},source.getBlob(),{fields:'id'});
   props_().setProperty(key,f.id);const s=sheet_('Register '+side.toUpperCase());s.setFrozenRows(1);
  }
 }
 props_().setProperty('INSTALLED','yes');console.log('Templates installed. Deploy as owner; Anyone access is needed for tablet and email-code login.');
}
