function equalValue_(a,b){return JSON.stringify(a===undefined?null:a)===JSON.stringify(b===undefined?null:b);}
function mergeCasePatch_(latest,patch,base,user,sc){
 const out=JSON.parse(JSON.stringify(patch)),sides=user.role==='FO'?['fo']:['fo','admin'];
 for(const side of sides){if(!patch[side])continue;const before=base[side]||{},local=patch[side],remote=latest[side]||{},merged=JSON.parse(JSON.stringify(remote)),groups={};
  for(const f of sc.fields.filter(f=>f.side===side&&f.group)){(groups[f.group]||(groups[f.group]=[])).push(f.id);}
  for(const ids of Object.values(groups)){const changed=ids.some(k=>!equalValue_(local[k],before[k]));if(changed&&ids.some(k=>!equalValue_(remote[k],before[k]))&&ids.some(k=>!equalValue_(remote[k],local[k])))throw Error('EDIT_CONFLICT: Another user changed '+'the selected options'+'. Your unsaved changes are still on screen.');}
  for(const key of new Set(Object.keys(before).concat(Object.keys(local)))){if(equalValue_(local[key],before[key]))continue;if(!equalValue_(remote[key],before[key])&&!equalValue_(remote[key],local[key]))throw Error('EDIT_CONFLICT: Another user changed '+((sc.fields.find(f=>f.side===side&&f.id===key)||{}).label||key)+'. Your unsaved changes are still on screen.');if(local[key]===undefined)delete merged[key];else merged[key]=local[key];}out[side]=merged;
  const extra=side+'Extra';if(!equalValue_(patch[extra]||[],base[extra]||[])){if(!equalValue_(latest[extra]||[],base[extra]||[])&&!equalValue_(latest[extra]||[],patch[extra]||[]))throw Error('EDIT_CONFLICT: Additional field positions changed.');}else out[extra]=latest[extra]||[];
 }
 if(patch.meta){out.meta=Object.assign({},latest.meta);for(const key of ['date','receptionist','company','companyId']){if(equalValue_(patch.meta[key],base.meta&&base.meta[key]))continue;if(!equalValue_(latest.meta[key],base.meta&&base.meta[key])&&!equalValue_(latest.meta[key],patch.meta[key]))throw Error('EDIT_CONFLICT: Another user changed '+key+'. Your unsaved changes are still on screen.');out.meta[key]=patch.meta[key];}}
 return out;
}
