function storeCase_(l,r){const text=JSON.stringify(r);let fileId=l.index.values[5]||'';if(text.length>45000){if(fileId)DriveApp.getFileById(fileId).setContent(text);else fileId=file_(folder_('RECORDS_ID'),r.id+'.json',r).getId();}sheet_('Cases').getRange(l.index.row,3,1,11).setNumberFormat('@').setValues([[safeCell_(r.fo.patientName||''),safeCell_(r.fo.passport||''),r.revision,fileId,r.created,r.updated,l.index.values[8]||'',l.index.values[9]||'',text.length<=45000?text:'',r.meta.date,false]]);l.index.values[5]=fileId;props_().setProperty('REGISTER_REV',uid_());}
function registerChanged_(a,b){const normalized=r=>{const f=Object.assign({},r.fo),d=Object.assign({},r.admin);for(const side of [f,d])for(const key of Object.keys(side))if(side[key]&&typeof side[key]==='object')delete side[key];return JSON.stringify([f,d,r.meta]);};return normalized(a)!==normalized(b);}
function patientDefaults_(u){const t=JSON.parse(JSON.stringify(template_()));if(u.role==='FO'){delete t.admin;delete t.editable.admin;}return t;}
function patientDefaults(token){return patientDefaults_(auth_(token));}
function receptionistName_(value){value=String(value||'').trim().replace(/\s+/g,' ');if(value.length<2||value.length>80||/[\x00-\x1f]/.test(value)||/^[=+@'\-]/.test(value))throw Error('Enter your Receptionist Name.');return value;}
function setReceptionistName(token,name){const u=auth_(token);if(u.role!=='FO')throw Error('Front Office access required.');const result=issueSession_(u,receptionistName_(name));CacheService.getScriptCache().remove('session:'+digest_(token));return result;}
function deleteCase(token,id,revision){auth_(token);return lock_(()=>{const u=auth_(token),l=load_(id),r=l.record;if(r.revision!==Number(revision))throw Error('Patient changed. Reload before deleting.');sheet_('Cases').getRange(l.index.row,13).setValue(true);for(const [side,col] of [['fo',8],['admin',9]]){const n=Number(l.index.values[col]);if(n){const s=sheet_('Register '+side.toUpperCase()),width=side==='fo'?34:16;s.getRange(n,1,1,width).setValues([Array(width).fill('')]);}}const rooms=roomSheet_(),room=roomRow_(id,rooms);if(room)rooms.getRange(room.row,4,1,3).setValues([['','','']]);for(const d of rows_('Devices'))if(d[5]){const req=json_(d[5]);if(req.caseId===id&&req.state==='pending'){req.state='cancelled';DriveApp.getFileById(d[5]).setContent(JSON.stringify(req));}}props_().setProperty('REGISTER_REV',uid_());props_().setProperty('ROOM_REV',uid_());audit_(auditActor_(u),'PATIENT_DELETE',id);return true;});}
function roomLinksSheet_(){return workflowSheet_('Room Links',['ID','Token hash','Role','Label','Active','Token','Created']);}
function listRoomLinks(token){super_(token);const s=roomLinksSheet_();return (s.getLastRow()>1?s.getRange(2,1,s.getLastRow()-1,7).getValues():[]).map(r=>({id:r[0],role:r[2],label:r[3],active:r[4]===true,url:r[4]===true?ScriptApp.getService().getUrl()+'?room='+encodeURIComponent(r[5]):''}));}
function createRoomLink(token,role,label){super_(token);if(!['SAMPLE','XRAY'].includes(role))throw Error('Select a room.');label=String(label||'').trim().slice(0,100);if(!label)throw Error('Enter a room link name.');return lock_(()=>{const u=super_(token),secret=uid_(),id=Utilities.getUuid();roomLinksSheet_().appendRow([id,digest_(secret),role,safeCell_(label),true,secret,new Date().toISOString()]);audit_(u.id,'ROOM_LINK_CREATE',id);return {id,role,label,url:ScriptApp.getService().getUrl()+'?room='+encodeURIComponent(secret)};});}
function revokeRoomLink(token,id){super_(token);return lock_(()=>{const u=super_(token),s=roomLinksSheet_(),rows=s.getLastRow()>1?s.getRange(2,1,s.getLastRow()-1,7).getValues():[],i=rows.findIndex(r=>r[0]===id);if(i<0)throw Error('Room link not found.');s.getRange(i+2,5).setValue(false);audit_(u.id,'ROOM_LINK_REVOKE',id);return true;});}
function roomLinkUser_(token){if(typeof token!=='string'||token.length<60||token.length>100)return null;const s=roomLinksSheet_(),rows=s.getLastRow()>1?s.getRange(2,1,s.getLastRow()-1,7).getValues():[],r=rows.find(r=>r[1]===digest_(token)&&r[4]===true);return r?{id:'room-link:'+r[0],email:'room-link:'+r[0],name:r[3],role:r[2],active:true,version:1,roomLink:true}:null;}

function upgradeFastRecords_(){if(props_().getProperty('FAST_STORAGE_VERSION')==='7')return;const s=sheet_('Cases'),count=s.getLastRow()-1;if(count>0){const rows=s.getRange(2,1,count,14).getValues(),data=rows.map(row=>{if(cellTrue_(row[12]))return row.slice(10,14);const r=migrateRecord_(row[10]?JSON.parse(row[10]):json_(row[5])),text=JSON.stringify(r);return [text.length<=45000?text:'',r.meta.date,false,row[13]||''];});s.getRange(2,11,count,4).setNumberFormat('@').setValues(data);}props_().setProperty('FAST_STORAGE_VERSION','7');}

function auditActor_(u){return u.role==='FO'&&u.receptionist?u.id+' · '+u.receptionist:u.id;}

/** Normalize Sheets Date objects before filtering or returning data to HTML. */
function cellTrue_(v){return v===true||String(v).toUpperCase()==='TRUE';}
function cellInstant_(v){if(Object.prototype.toString.call(v)==='[object Date]')return Number.isNaN(v.getTime())?'':v.toISOString();return v===null||v===undefined?'':String(v);}
function cellDate_(v){try{if(Object.prototype.toString.call(v)==='[object Date]')return Number.isNaN(v.getTime())?'':Utilities.formatDate(v,'Indian/Maldives','dd/MM/yyyy');let text=String(v||'').trim();if(!text)return '';if(/^\d{4}-\d{2}-\d{2}T/.test(text)){const d=new Date(text);return Number.isNaN(d.getTime())?'':Utilities.formatDate(d,'Indian/Maldives','dd/MM/yyyy');}const m=text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(m)text=m[1].padStart(2,'0')+'/'+m[2].padStart(2,'0')+'/'+m[3];return dateText_(text);}catch(e){return '';}}
function caseDate_(row){if(row[10])try{const r=JSON.parse(row[10]),date=cellDate_(r.meta&&r.meta.date);if(date)return date;}catch(e){}return cellDate_(row[11])||cellDate_(row[6]);}
function repairPatientData(token){super_(token);return lock_(()=>{super_(token);return repairPatientData_();});}
function repairPatientData_(){const sheet=sheet_('Cases'),count=sheet.getLastRow()-1,summary={patients:0,queued:0,issues:[]};if(count>0){const rows=sheet.getRange(2,1,count,14).getValues(),metadata=rows.map(row=>row.slice(2,13));for(let i=0;i<rows.length;i++){const row=rows[i];if(!row[0])continue;if(cellTrue_(row[12])){const room=roomRow_(row[0],roomSheet_());if(room)roomSheet_().getRange(room.row,4,1,3).setValues([['','','']]);continue;}try{const r=migrateRecord_(row[10]?JSON.parse(row[10]):json_(row[5]));const text=JSON.stringify(r);metadata[i]=[safeCell_(r.fo.patientName||''),safeCell_(r.fo.passport||''),r.revision,row[5]||'',r.created,r.updated,row[8]||'',row[9]||'',text.length<=45000?text:'',r.meta.date,false];syncRoom_(r);summary.patients++;if(String(r.fo.patientName||'').trim()&&String(r.fo.passport||'').trim())summary.queued++;}catch(e){summary.issues.push({id:String(row[0]),error:String(e.message||e)});}}sheet.getRange(2,3,count,11).setNumberFormat('@').setValues(metadata);}props_().setProperty('FAST_STORAGE_VERSION','7.4');props_().setProperty('REGISTER_REV',uid_());props_().setProperty('ROOM_REV',uid_());console.log(JSON.stringify(summary));return summary;}

function roomEpoch_(){const p=props_();return (p.getProperty('ROOM_REV')||'')+':'+(p.getProperty('REGISTER_REV')||'');}

function appendTextRow_(sheet,values){const row=sheet.getLastRow()+1;if(row>sheet.getMaxRows())sheet.insertRowsAfter(sheet.getMaxRows(),100);sheet.getRange(row,1,1,values.length).setNumberFormat('@').setValues([values]);return row;}
